const express = require('express');
const { createYoga, createSchema } = require('graphql-yoga');
const Redis = require('ioredis');

const redis = new Redis(process.env.REDIS_URL);
const app = express();

const typeDefs = `
  type VehicleTelematicsReport @key(fields: "vin") {
    vin: ID!
    latitude: Float!
    longitude: Float!
    odometerKm: Int!
    fuelLevelPct: Float!
    lastEnginePing: String!
  }

  type Query {
    telematicsOnline: Boolean
  }
`;

const resolvers = {
  VehicleTelematicsReport: {
    __resolveReference: async (ref, { redis }) => {
      // Direct cache lookup for vehicle telematics state by VIN
      const data = await redis.hgetall(`telematics:${ref.vin}`);
      if (!data || !data.vin) return null;
      return {
        vin: data.vin,
        latitude: parseFloat(data.lat),
        longitude: parseFloat(data.lon),
        odometerKm: parseInt(data.odometer, 10),
        fuelLevelPct: parseFloat(data.fuel),
        lastEnginePing: data.timestamp
      };
    }
  }
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  context: ({ req }) => ({
    redis,
    fleetTenant: req.headers['x-fleet-tenant']
  })
});

app.all('/graphql/telematics', yoga);
app.listen(7000);

